<script setup>
import {ref,computed,onMounted} from 'vue';
const props=defineProps({source:Object,roles:Array,snapshots:Array,groups:Array});const emit=defineEmits(['updated','close']);
const selected=ref(''),name=ref(''),scope=ref('all'),targets=ref([props.source.key]),search=ref(''),group=ref('*'),busy=ref(false),error=ref(''),message=ref(''),nameInput=ref(null);
const chosen=computed(()=>props.snapshots.find(s=>s.id===selected.value));
const scopeLabel=s=>({all:'全部任务',daily:'每日任务',weekly:'每周任务'}[s]||s);
const filtered=computed(()=>props.roles.filter(r=>(group.value==='*'||(r.group_id||'')===group.value)&&(!search.value||(r.name+' '+r.server).includes(search.value.trim()))));
function selectSnapshot(){name.value=chosen.value?.name||'';scope.value=chosen.value?.scope||'all';message.value='';error.value=''}
function toggle(key,checked){targets.value=checked?[...new Set([...targets.value,key])]:targets.value.filter(k=>k!==key)}
async function run(action,payload){if(busy.value)return;busy.value=true;error.value='';message.value='';try{
 const r=await window.pywebview.api.task_checklist('snapshots',{action,...payload});if(!r.ok)throw Error(r.error);emit('updated',r.data.snapshot);
 if(action==='save'){selected.value=r.data.snapshot_id;message.value='已保存当前角色的 '+r.data.count+' 项任务配置'}
 if(action==='apply')message.value='已应用到 '+r.data.applied+' 个角色，共 '+r.data.count+' 项任务配置';
 if(action==='remove'){selected.value='';name.value='';message.value='已删除快照，角色现有设置保留'}
 }catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>nameInput.value?.focus());
</script>
<template><Teleport to="body"><div class="snapshot-mask" @keydown.esc.stop="!busy&&emit('close')"><section class="snapshot-dialog" role="dialog" aria-modal="true" aria-label="任务设置快照"><header><div><h2>任务设置快照</h2><p>保存监控开关和重要程度，用于不同角色的日常安排。</p></div><button :disabled="busy" @click="emit('close')" aria-label="关闭任务快照">×</button></header><div class="snapshot-body"><div class="snapshot-columns"><section><h3>保存当前配置 <small>{{source.name}} · {{source.server}}</small></h3><label>快照名称<input ref="nameInput" aria-label="快照名称" v-model="name" maxlength="40" placeholder="例如：主号日常、小号每周" :disabled="busy"></label><label>保存范围<select aria-label="快照保存范围" v-model="scope" :disabled="busy"><option value="all">全部任务（每日 + 每周）</option><option value="daily">仅每日任务</option><option value="weekly">仅每周任务</option></select></label><div class="snapshot-buttons"><button :disabled="busy||!name.trim()" @click="run('save',{name,scope,role:source.key})">保存为新快照</button><button :disabled="busy||!chosen||!name.trim()" @click="run('save',{id:selected,name,scope,role:source.key})">更新所选快照</button></div><p class="hint">快照仅复制任务配置，任务进度、完成状态、角色分组及存量记录均保留。</p></section><section><h3>选择已保存的快照 <small>{{snapshots.length}} 份</small></h3><select class="snapshot-picker" aria-label="选择任务快照" v-model="selected" @change="selectSnapshot" :disabled="busy"><option value="">请选择快照</option><option v-for="s in snapshots" :key="s.id" :value="s.id">{{s.name}} · {{scopeLabel(s.scope)}}</option></select><div v-if="chosen" class="snapshot-info"><strong>{{chosen.name}}</strong><p>{{scopeLabel(chosen.scope)}} · {{chosen.count}} 项任务</p><p>启用 {{chosen.enabled}} 项 · 重要 {{chosen.important}} 项 · 不提醒 {{chosen.muted}} 项</p><p>来源：{{chosen.source}} · {{chosen.at.slice(0,16).replace('T',' ')}}</p><button class="snapshot-remove" :disabled="busy" @click="run('remove',{id:selected})">删除快照</button></div><p v-else class="hint">先保存一份配置，或选择已有快照。</p></section></div><section class="snapshot-targets"><div class="targets-heading"><h3>应用到角色 <small>已选 {{targets.length}} 位</small></h3><div class="snapshot-buttons"><button :disabled="busy" @click="targets=[...new Set([...targets,...filtered.map(r=>r.key)])]">全选当前列表</button><button :disabled="busy" @click="targets=[]">清空选择</button></div></div><div class="target-filters"><input aria-label="搜索快照目标角色" v-model="search" placeholder="搜索角色 / 区服" :disabled="busy"><select aria-label="快照目标分组" v-model="group" :disabled="busy"><option value="*">全部分组</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.name}}</option></select></div><div class="target-list"><label v-for="r in filtered" :key="r.key"><input type="checkbox" :aria-label="'选择目标 '+r.name" :checked="targets.includes(r.key)" :disabled="busy" @change="toggle(r.key,$event.target.checked)"><span>{{r.name}}<small>{{r.server}}</small></span></label><p v-if="!filtered.length" class="hint">没有匹配的角色</p></div></section><p class="error" v-if="error" role="alert">{{error}}</p><p class="success" v-if="message" role="status">{{message}}</p></div><footer><span>仅覆盖快照范围内的监控开关和重要程度。</span><button class="primary" :disabled="busy||!chosen||!targets.length" @click="run('apply',{id:selected,roles:targets})">{{busy?'正在处理…':'应用到所选 '+targets.length+' 个角色'}}</button></footer></section></div></Teleport></template>
<style scoped>
.snapshot-mask{position:fixed;inset:0;z-index:1200;background:#2c251c66;backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:24px}.snapshot-dialog{width:min(900px,100%);max-height:90dvh;background:#fffcf6;border:1px solid #dfd3bf;border-radius:10px;display:flex;flex-direction:column;overflow:hidden;color:#3b413b;box-shadow:0 18px 60px #352a2426}header{display:flex;justify-content:space-between;align-items:flex-start;padding:22px 24px 17px;border-bottom:1px solid #e8dfcf;gap:15px;flex:none}h2{font-size:20px;margin:0 0 7px}h3{font-size:13px;margin:0 0 14px;font-weight:600}h3 small{font-size:11px;font-weight:400;color:#998a74;margin-left:8px}p,.hint{font-size:11px;color:#998a74;line-height:1.8;margin:0}.snapshot-body{padding:22px 24px;overflow:auto;min-height:0}.snapshot-columns{display:grid;grid-template-columns:1fr 1fr;gap:26px}.snapshot-columns section{min-width:0}.snapshot-columns section>label{display:block;font-size:12px;color:#897c69;margin-bottom:12px}.snapshot-columns label input,.snapshot-columns label select,.snapshot-picker{display:block;width:100%;margin-top:7px}button,input:not([type=checkbox]),select{font:inherit;font-size:12px;border:1px solid #dfd3bf;border-radius:6px;background:#fffcf6;color:inherit;padding:8px 10px;min-width:0}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}header>button{padding:2px 8px;font-size:22px;border:0;background:transparent;color:#a18d71}.snapshot-buttons{display:flex;gap:8px;flex-wrap:wrap}.snapshot-columns .hint{margin-top:14px}.snapshot-info{padding:15px;background:#f1ecdf;border-radius:7px;margin-top:14px;line-height:1.8}.snapshot-info strong{font-size:13px}.snapshot-remove{margin-top:12px;color:#9d8061}.snapshot-targets{border-top:1px solid #e8dfcf;padding-top:20px;margin-top:22px}.targets-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.targets-heading h3{margin:0}.target-filters{display:flex;gap:10px;margin:14px 0}.target-filters input{flex:1}.target-filters select{max-width:200px}.target-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:8px;max-height:240px;overflow:auto;overscroll-behavior:contain}.target-list label{display:flex;align-items:center;gap:10px;padding:9px 10px;border:1px solid #e8dfcf;border-radius:6px;font-size:12px;cursor:pointer}.target-list label span{min-width:0;overflow-wrap:anywhere}.target-list small{display:block;font-size:10px;color:#a08e73;margin-top:3px}input[type=checkbox]{accent-color:#456052;flex:none}footer{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:16px 24px;border-top:1px solid #e8dfcf;flex:none}footer span{font-size:11px;color:#998a74}button.primary{background:#456052;border-color:#456052;color:#fff}.error{color:#ad513d;margin-top:14px}.success{color:#56734b;margin-top:14px}@media(max-width:800px){.snapshot-mask{padding:14px}.snapshot-columns{grid-template-columns:1fr;gap:20px}.snapshot-body{padding:18px}header{padding:18px}footer{flex-wrap:wrap;padding:14px 18px}.target-list{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}}
</style>
